import { NotShared, Shared, UsingImmer } from "./1Adding Interactivity/5zCoreCocept"
import Sub from "./subReLearn"
import "./ReLearn.css"
import {useState} from "react"

export default function () {
  const [obj, setObj] = useState([{a:1,elem: <p>anjass</p>},{a:2, elem: <div>wow</div>},{a:3, elem: <section>real</section>}])
  const [id,setId] = useState(3)
  const selecting = obj.find(item => item.a === id)
  return (
    <>
    {selecting.elem}
    <button onClick={() => {setId(id)}}>&larr;</button>
    <button onClick={() => {}}>&rarr;</button>
    </>
  );
}


